  '源道方': { n: 'Minamoto no Michikata', tip: ['Minamoto no Michikata', 'Lived: 968–1044', 'Office: Acting Middle Counselor', "Family: Son of Minamoto no Shigenobu; his mother was a daughter of Minamoto no Takaakira", 'Note: Father of Minamoto no Tsunenobu'] },
