  '源基平': { n: 'Minamoto no Motohira', tip: ['Minamoto no Motohira', 'Lived: 1026–1064', 'Office: Councillor', 'Rank: Junior Second Rank', 'Family: Son of Prince Atsuakira (Koichijō-in)'] },
  '白河': { n: 'Shirakawa', tip: ['Emperor Shirakawa', '72nd emperor', 'Lived: 1053–1129', 'Reign: 1073–1087', 'Note: After giving up the throne, he began rule by retired emperors (insei)'] },
  '藤原賢子': { n: 'Kenshi', tip: ['Fujiwara no Kenshi', 'Lived: 1057–1084', 'Family: Daughter of Minamoto no Akifusa; adopted by Fujiwara no Morozane', 'Note: Empress (chūgū) of Emperor Shirakawa. Mother of Emperor Horikawa'] },
