  '堀河': { n: 'Horikawa', tip: ['Emperor Horikawa', '73rd emperor', 'Lived: 1079–1107', 'Reign: 1087–1107'] },
  '藤原苡子': { n: 'Ishi', tip: ['Fujiwara no Ishi', 'Lived: 1076–1103', 'Family: Daughter of Fujiwara no Sanesue', 'Note: Consort (nyōgo) of Emperor Horikawa. She died just after giving birth to Emperor Toba'] },
