  '待賢門院': { n: 'Taikenmon-in', tip: ['Taikenmon-in', "Note: Empress (chūgū) of Emperor Toba (Fujiwara no Shōshi). Mother of Emperors Sutoku and Go-Shirakawa. The Kojidan has a story that Sutoku was really the son of Retired Emperor Shirakawa and Shōshi. Horikawa, attendant to Empress Taiken, served her"] },
  '鳥羽': { n: 'Toba', tip: ['Emperor Toba', '74th emperor', 'Lived: 1103–1156', 'Reign: 1107–1123', 'Note: After giving up the throne, he ruled as retired emperor'] },
  '美福門院': { n: 'Bifukumon-in', tip: ['Bifukumon-in', 'Note: Empress (kōgō) of Emperor Toba (Fujiwara no Tokuko). Mother of Emperor Konoe and Princess Akiko (Shōshi)'] },
  '崇徳': { n: 'Sutoku', tip: ['Emperor Sutoku', '75th emperor', 'Lived: 1119–1164', 'Reign: 1123–1142', 'Hyakunin Isshu: Poet of Poem 77, "Se wo hayami..."', 'Note: In the Hyakunin Isshu he is called Retired Emperor Sutoku. He lost the Hōgen Rebellion (1156) and was exiled to Sanuki'] },
  '後白河': { n: 'Go-Shirakawa', tip: ['Emperor Go-Shirakawa', '77th emperor', 'Lived: 1127–1192', 'Reign: 1155–1158', 'Note: After giving up the throne, he ruled as retired emperor for a long time. He compiled the Ryōjin Hishō, a collection of popular songs (imayō)'] },
