  '具平親王の次女': { n: "Prince Tomohira's second daughter", tip: ['Second daughter of Prince Tomohira', 'Family: Daughter of Prince Tomohira, a son of Emperor Murakami', "Note: Prince Atsuyasu's consort and Fujiwara no Genshi's mother"] },
  '禎子内親王': { n: 'Princess Yoshiko', tip: ['Princess Yoshiko (Teishi)', 'Lived: 1013–1094', 'Family: Daughter of Emperor Sanjō and Empress Kenshi', 'Note: Empress (kōgō) of Emperor Go-Suzaku and mother of Emperor Go-Sanjō. Her title as a retired empress was Yōmeimon-in'] },
  '嫄子': { n: 'Genshi', tip: ['Fujiwara no Genshi', 'Lived: 1016–1039', "Family: Daughter of Prince Atsuyasu; her mother was Prince Tomohira's second daughter. Adopted by Fujiwara no Yorimichi", 'Note: Empress (chūgū) of Emperor Go-Suzaku. Mother of Princess Yūshi and Princess Baishi'] },
  '後三条': { n: 'Go-Sanjō', tip: ['Emperor Go-Sanjō', '71st emperor', 'Lived: 1034–1073', 'Reign: 1068–1073', 'Family: Son of Emperor Go-Suzaku; his mother was Princess Yoshiko, a daughter of Emperor Sanjō', 'Note: An emperor without Fujiwara in-laws, he ruled directly himself'] },
  '祐子内親王': { n: 'Princess Yūshi', tip: ['Princess Yūshi', 'Family: Daughter of Emperor Go-Suzaku and Empress Genshi', 'Note: Sagami, Kii, and others served her'] },
  '禖子内親王': { n: 'Princess Baishi', tip: ['Princess Baishi', 'Lived: 1039–1096', 'Family: Daughter of Emperor Go-Suzaku and Empress Genshi', 'Note: Became the Kamo priestess and was called Rokujō Saiin. She often held poetry contests'] },
