  '相模': { n: 'Sagami', tip: ['Sagami', 'Lived: c. 998–after 1061', 'Family: Adopted daughter of Minamoto no Yorimitsu (her real father is unknown); her mother was a daughter of Yoshishige no Yasuaki', 'Hyakunin Isshu: Poet of Poem 65, "Uramiwabi..."', 'Note: She was called Sagami because her husband, Ōe no Kinsuke, was Governor of Sagami'] },
