  // 63.html（左京大夫道雅）
  '娍子': { n: 'Seishi', tip: ['Fujiwara no Seishi', 'Lived: 972–1025', 'Family: Eldest daughter of Fujiwara no Naritoki; her younger brother was Michitō', 'Note: Entered the court in 991 as consort of the future Emperor Sanjō while he was crown prince, and later became empress (kōgō). Mother of Prince Atsuakira, Princess Masako, and others'] },
  '宣孝の娘': { n: "Nobutaka's daughter", tip: ['Daughter of Fujiwara no Nobutaka', 'Note: Principal wife of Fujiwara no Michimasa'] },
  '藤原道雅': { n: 'Master of the Left Capital Michimasa', tip: ['Fujiwara no Michimasa', 'Family: Son of Fujiwara no Korechika', 'Hyakunin Isshu: Poet of Poem 63, "Ima wa tada..."', 'Note: In 1016 he became Middle Captain of the Left Palace Guards and Junior Third Rank. He had a secret affair with Princess Masako after she returned from serving as the Ise priestess; it was discovered the next year, and Retired Emperor Sanjō punished him. His wild behavior never stopped, and he was called "the wild third rank" (Ara-sanmi) and "the wicked third rank" (Aku-sanmi)'] },
  '惟仲の娘': { n: "Korenaka's daughter", tip: ['Daughter of Taira no Korenaka (Yamato no Senji)', 'Note: Second wife of Fujiwara no Michimasa'] },
  '当子内親王': { n: 'Princess Masako', tip: ['Princess Masako', 'Lived: 1001–1022', 'Family: Daughter of Emperor Sanjō and Empress Seishi', 'Note: After returning from serving as the Ise priestess, she had a secret affair with Fujiwara no Michimasa. They were forced apart, and she later fell ill and became a nun'] },
  '上東門院中将': { n: 'Jōtōmon-in no Chūjō', tip: ['Jōtōmon-in no Chūjō', 'Family: Daughter of Fujiwara no Michimasa'] },
  '観尊': { n: 'Kanson', tip: ['Kanson', 'Family: Son of Fujiwara no Michimasa'] },
