  // 56.html（和泉式部）
  '昌子内親王': { n: 'Princess Shōshi', tip: ['Princess Shōshi', "Note: Empress of Emperor Reizei. Izumi Shikibu's father, Ōe no Masamune, served her as Senior Secretary of the Grand Empress Dowager's Household, and her mother is said to have been the princess's nurse (or the nurse's daughter)"] },
