  '超子': { n: 'Chōshi', tip: ['Fujiwara no Chōshi', 'Family: Eldest daughter of Fujiwara no Kaneie and Tokihime', 'Note: Consort (nyōgo) of Emperor Reizei. Mother of Emperor Sanjō, Prince Tametaka, and Prince Atsumichi'] },
  '詮子': { n: 'Senshi', tip: ['Fujiwara no Senshi', 'Lived: 962–1002', 'Family: Daughter of Fujiwara no Kaneie and Tokihime', 'Note: Consort (nyōgo) of Emperor En\'yū and mother of Emperor Ichijō. Her title as a retired empress was Higashi Sanjō-in'] },
