  '高階良臣': { n: 'Takashina no Yoshiomi', tip: ['Takashina no Yoshiomi', 'Lived: 898–980', 'Office: Minister of the Imperial Household', 'Rank: Junior Fourth Rank, Lower Grade', 'Family: Son of Takashina no Moronao'] },
  '円融': { n: "En'yū", tip: ["Emperor En'yū", '64th emperor', 'Lived: 959–991', 'Reign: 969–984'] },
