  '教通': { n: 'Norimichi', tip: ['Fujiwara no Norimichi', 'Lived: 996–1075', 'Office: Kampaku (chief adviser) and Chancellor of the Realm', 'Rank: Junior First Rank; Senior First Rank after death'] },
  '威子': { n: 'Ishi', tip: ['Fujiwara no Ishi', 'Lived: 1000–1036', 'Family: Daughter of Fujiwara no Michinaga and Minamoto no Tomoko', 'Note: Empress (chūgū) of Emperor Go-Ichijō. On the day she was made empress, Michinaga composed his poem "Kono yo wo ba..."'] },
  '嬉子': { n: 'Kishi', tip: ['Fujiwara no Kishi', 'Lived: 1007–1025', 'Family: Daughter of Fujiwara no Michinaga and Minamoto no Tomoko', 'Note: Consort of Emperor Go-Suzaku while he was crown prince. She died just after giving birth to Emperor Go-Reizei'] },
  '妍子': { n: 'Kenshi', tip: ['Fujiwara no Kenshi', 'Lived: 994–1027', 'Family: Second daughter of Fujiwara no Michinaga and Minamoto no Tomoko', 'Note: Empress (chūgū) of Emperor Sanjō and mother of Princess Yoshiko (Teishi)'] },
